import React from 'react';

const ResultsPage = ({ data, onNavigate }) => {
    const { score = 0, count = 0, percentage = 0, grade = 'N/A' } = data || {};

    const getGradeColor = (grade) => {
        switch(grade) {
            case 'A': return '#4CAF50';
            case 'B': return '#8BC34A';
            case 'C': return '#FFC107';
            case 'D': return '#FF9800';
            case 'F': return '#f44336';
            default: return '#9E9E9E';
        }
    };

    const getEncouragementMessage = (percentage) => {
        if (percentage >= 90) return "Outstanding work! You're a quiz master! 🌟";
        if (percentage >= 80) return "Great job! Keep up the good work! 👍";
        if (percentage >= 70) return "Good effort! You're getting there! 💪";
        if (percentage >= 60) return "Not bad! A bit more practice will help! 📚";
        return "Keep practicing! You'll improve! 🎯";
    };

    return (
        <div style={{
            color: 'white',
            backgroundColor: '#1e3a8a',
            minHeight: '100vh',
            padding: '40px',
            fontFamily: 'Sans-Serif'
        }}>
            <h1 style={{ fontSize: '3em', marginBottom: '40px' }}>Quiz Results</h1>

            <div style={{
                maxWidth: '600px',
                margin: '0 auto',
                backgroundColor: 'rgba(255, 255, 255, 0.1)',
                borderRadius: '20px',
                padding: '40px',
                boxShadow: '0 8px 32px rgba(0, 0, 0, 0.3)'
            }}>
                <div style={{
                    fontSize: '4em',
                    fontWeight: 'bold',
                    color: getGradeColor(grade),
                    marginBottom: '20px',
                    textShadow: '2px 2px 4px rgba(0,0,0,0.3)'
                }}>
                    Grade: {grade}
                </div>

                <div style={{
                    fontSize: '2em',
                    marginBottom: '30px',
                    padding: '20px',
                    backgroundColor: 'rgba(255, 255, 255, 0.1)',
                    borderRadius: '10px'
                }}>
                    <div>Score: <strong>{score} / {count}</strong></div>
                    <div style={{ marginTop: '10px' }}>
                        Percentage: <strong>{percentage}%</strong>
                    </div>
                </div>

                <div style={{
                    fontSize: '1.3em',
                    fontStyle: 'italic',
                    marginBottom: '30px',
                    padding: '20px',
                    backgroundColor: 'rgba(255, 255, 255, 0.05)',
                    borderRadius: '10px',
                    borderLeft: '4px solid ' + getGradeColor(grade)
                }}>
                    {getEncouragementMessage(percentage)}
                </div>

                <div style={{
                    marginTop: '40px'
                }}>
                    <button 
                        onClick={() => onNavigate('quiz')}
                        style={{
                            padding: '15px 40px',
                            fontSize: '18px',
                            marginRight: '10px',
                            cursor: 'pointer',
                            backgroundColor: '#4CAF50',
                            color: 'white',
                            border: 'none',
                            borderRadius: '5px',
                            boxShadow: '0 4px 6px rgba(0,0,0,0.2)',
                            transition: 'all 0.3s'
                        }}
                        onMouseOver={(e) => e.target.style.transform = 'scale(1.05)'}
                        onMouseOut={(e) => e.target.style.transform = 'scale(1)'}
                    >
                        Take Quiz Again
                    </button>

                    <button 
                        onClick={() => onNavigate('home')}
                        style={{
                            padding: '15px 40px',
                            fontSize: '18px',
                            cursor: 'pointer',
                            backgroundColor: '#2196F3',
                            color: 'white',
                            border: 'none',
                            borderRadius: '5px',
                            boxShadow: '0 4px 6px rgba(0,0,0,0.2)',
                            transition: 'all 0.3s'
                        }}
                        onMouseOver={(e) => e.target.style.transform = 'scale(1.05)'}
                        onMouseOut={(e) => e.target.style.transform = 'scale(1)'}
                    >
                        Home
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ResultsPage;
